/** routing.levels (LevelRules in config.py). Patterns are matched against the last two messages from the person. */
export const LEVELS = {
  general: "Plain text that isn't coding: no tools and no code-like text. Default 2.",
  short: "Plain text whose whole request (history and system prompt included) is under the token count next to it: a question on its own, such as \"What's the capital of Portugal?\". Analysis wording still wins. Default 1.",
  short_tokens: "How short a request must be to count as a question on its own. This is the only place length counts, and it only lowers a level. 0 turns it off, so every plain-text request is general work. Default 400.",
  analysis: "Plain text with analysis wording (the list below). Default 3.",
  coding: "Any request with tools, or text that looks like code (the list below), when its wording matches none of the coding lists. Tools say the work is coding, not how hard it is. Default 3.",
  simple: "Coding whose wording matches the simple list (tests, renames, typos, docstrings) and no harder one. Default 2.",
  hardest: "Coding whose wording matches the hardest list (system design, proofs, codebase-wide refactors). Default 5.",
  hard_signals: "How many different hard-wording patterns count: \"deadlocks under load\" is two signs of hard work. Default 2.",
  correction_raise: "A new prompt that says the last answer was wrong (\"that's wrong\", \"still not working\", \"revert\") goes this many levels up, to 5 at most. Only the newest prompt is read. 0 turns it off. Default 1.",
  agent_by_tools: "Yes: a request with at least the number of tools below is coding at the agent level, whatever its wording (the rule before decision 61). Claude Code and Codex send dozens of tools on every request, so this puts every task they do at that level or above. Default no.",
  agent: "With the tool count setting the level: coding with at least the number of tools next to it. Default 4.",
  agent_tools: "How many tools make a request an agent's. The learned router uses it either way. Default 5.",
  hard_raise: "Coding with hard wording (the list below) goes this many levels up for each different pattern it matches (up to the count next to it), to 5 at most. 0 turns the list off. Default 1.",
  coding_words: "One pattern per line: Python regular expressions, matched ignoring case. `\\b` marks the start or end of a word, so `\\bbug\\b` matches \"bug\" but not \"debug\", and `\\s` is a space (spaces at the start or end of a line are dropped). A pattern that matches empty text is refused: it would match every request. Requests show which pattern matched, never the text.",
  simple_words: "One pattern per line, as for code-like text. Kinds of task a cheaper model does well; a harder list that also matches wins. Empty turns it off.",
  hard_words: "One pattern per line, as for code-like text. Hard wording only raises coding requests.",
  hardest_words: "One pattern per line, as for code-like text. Puts coding at the hardest level. Empty turns it off.",
  analysis_words: "One pattern per line, as for code-like text. For plain-text requests only.",
} as const;

